// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {OperatorLockable} from "./OperatorLockable.sol";
import {DexTreasury} from "./DexTreasury.sol";
import {IFreezeHook} from "./interfaces/IFreezeHook.sol";
import {ITokenSource} from "./interfaces/ITokenSource.sol";

contract Freezer is OperatorLockable, DexTreasury, ITokenSource {
    using SafeERC20 for IERC20;
    using SafeERC20 for IERC20Metadata;

    struct Frost {
        uint256 amount;
        address owner;
        uint8 tier;
        uint256 frozenAt;
        uint256 ownedAt;
    }

    struct Account {
        uint256 accruedNum;
        uint256 lastAccrualAt;
        uint256 lastClaimAt;
        uint256 firstFreezeAt;
        uint256 frostCount;
    }

    struct AccountView {
        uint256 accruedNum;
        uint256 lastAccrualAt;
        uint256 lastClaimAt;
        uint256 firstFreezeAt;
        uint256 frostCount;
        uint256 frozenTotal;
    }

    struct TierInfo {
        uint8 tier;
        uint256 term;
        uint256 weight;
    }

    struct FrostView {
        uint256 id;
        address owner;
        uint8 tier;
        uint256 amount;
        uint256 frozenAt;
        uint256 ownedAt;
        uint256 unfreezeAt;
        uint256 lockedTill;
        address lockedFor;
    }

    uint256 public constant MAX_FROSTS = 100;
    uint256 public constant CLAIM_COOLDOWN = 1 days;

    uint256 public constant DENOM = 3650 days;
    uint256 public constant YEAR = 365 days;
    uint8 public constant TIERS = 3;

    IERC20Metadata private immutable _token;

    uint256 public immutable candidacyFee;

    uint256 public nextFrostId = 1;
    uint256 public totalFrozen;
    uint256 public activeFrosts;
    IFreezeHook private immutable _freezeHook;
    address private immutable _freezerMarket;

    mapping(uint8 tier => uint256) public totalFrozenIn;
    mapping(uint8 tier => uint256) public activeFrostsIn;
    mapping(address owner => Account) private _accounts;
    mapping(address owner => mapping(uint8 tier => uint256)) private _tierTotal;
    mapping(uint256 frostId => Frost) private _frosts;

    event CandidacyFeeChanged(uint256 oldFee, uint256 newFee);
    event FrostCreated(uint256 indexed id, address indexed owner);
    event FrostChanged(uint256 indexed id);
    event FrostRemoved(uint256 indexed id, address indexed owner);
    event Frozen(uint256 indexed id, address indexed owner, uint8 tier, uint256 amount);
    event Unfrozen(uint256 indexed id, address indexed owner, uint8 tier, uint256 amount, uint256 left);
    event Merged(uint256 indexed id, uint256 indexed intoId, address indexed owner, uint8 tier);

    event Upgraded(uint256 indexed id, address indexed owner, uint8 fromTier, uint8 toTier, uint256 amount, uint256 frozenAt);
    event Transferred(
        uint256 indexed id,
        uint256 indexed remainderId,
        address indexed from,
        address to,
        uint8 tier,
        uint256 amount,
        uint256 frozenAt,
        uint256 lockedTill
    );
    event Returned(uint256 indexed id, address indexed from, address indexed to, uint8 tier, uint256 amount);
    event Claimed(address indexed owner, uint256 claimAmount);

    error InvalidTier(uint8 tier);
    error ZeroAmount();
    error ZeroAddress();
    error InvalidReceiver(address to);
    error NonexistentFrost(uint256 id);
    error IncorrectOwner(uint256 id, address owner, address expected);
    error FrostLocked(uint256 id, uint256 lockedTill);
    error FrostNotLocked(uint256 id);
    error StillFrozen(uint256 id, uint256 unfreezeAt);
    error InsufficientFrost(uint256 id, uint256 balance, uint256 needed);
    error TooManyFrosts(address owner, uint256 max);
    error TierMismatch(uint256 id, uint8 tier, uint8 expected);
    error NotAnUpgrade(uint256 id, uint8 tier, uint8 newTier);
    error InvalidListLength(uint256 length, uint256 minimum);
    error ClaimTooEarly(address owner, uint256 availableAt);
    error NothingToClaim(address owner);
    error RewardsDepleted();
    error AddressWithoutCode(address address_);
    error TreasuryBelowFrozen(uint256 balance, uint256 frozen);
    error OnlyMarketAccess();

    constructor(
        IERC20Metadata token_,
        uint256 dexSellCap_,
        address freezeHook_,
        address freezerMarket_,
        address dexModule_,
        Config memory dex
    ) DexTreasury(dexModule_, address(token_), dexSellCap_, dex) {
        require(address(token_) != address(0) && freezerMarket_ != address(0), ZeroAddress());
        require(freezeHook_ == address(0) || freezeHook_.code.length != 0, AddressWithoutCode(freezeHook_));
        require(freezerMarket_.code.length != 0, AddressWithoutCode(freezerMarket_));

        _token = token_;
        _freezeHook = IFreezeHook(freezeHook_);
        _freezerMarket = freezerMarket_;
        candidacyFee = 100 * 10 ** token_.decimals();

        emit CandidacyFeeChanged(0, candidacyFee);
    }

    function freeze(uint8 tier, uint256 amount, address referrer) external returns (uint256 id) {
        require(tier < TIERS, InvalidTier(tier));
        require(amount != 0, ZeroAmount());

        address sender = _msgSender();
        _requireSlot(sender);

        _token.safeTransferFrom(sender, address(this), amount);

        id = _freeze(sender, tier, amount);
        _notifyFreezeHook(sender, referrer, amount);
    }

    function unfreeze(uint256[] calldata ids) external returns (uint256 released) {
        require(ids.length != 0, InvalidListLength(ids.length, 1));

        released = 0;

        address sender = _msgSender();
        _settle(sender);

        for (uint256 i = 0; i < ids.length; ++i) {
            uint256 id = ids[i];
            Frost memory frost = _requireFrostOf(sender, id);

            _requireFree(id);

            uint256 unfreezeAt = _unfreezeAt(frost);
            require(unfreezeAt <= block.timestamp, StillFrozen(id, unfreezeAt));

            released += frost.amount;

            _tierTotal[sender][frost.tier] -= frost.amount;
            totalFrozenIn[frost.tier] -= frost.amount;
            _destroy(sender, id);

            emit Unfrozen(id, sender, frost.tier, frost.amount, 0);
        }

        totalFrozen -= released;
        _onStakeChanged(sender);

        _token.safeTransfer(sender, released);
    }

    function unfreezeOne(uint256 id, uint256 amount) external {
        require(amount != 0, ZeroAmount());

        address sender = _msgSender();
        Frost memory frost = _requireFrostOf(sender, id);

        _requireFree(id);
        require(amount <= frost.amount, InsufficientFrost(id, frost.amount, amount));

        uint256 unfreezeAt = _unfreezeAt(frost);
        require(unfreezeAt <= block.timestamp, StillFrozen(id, unfreezeAt));

        _settle(sender);

        uint256 left = frost.amount - amount;
        if (left == 0) {
            _destroy(sender, id);
        } else {
            _frosts[id].amount = left;
            emit FrostChanged(id);
        }

        _tierTotal[sender][frost.tier] -= amount;
        totalFrozen -= amount;
        totalFrozenIn[frost.tier] -= amount;
        _onStakeChanged(sender);

        _token.safeTransfer(sender, amount);

        emit Unfrozen(id, sender, frost.tier, amount, left);
    }

    function merge(uint256[] calldata ids) external returns (uint256 newId) {
        require(ids.length >= 2, InvalidListLength(ids.length, 2));

        address sender = _msgSender();
        _settle(sender);

        uint8 tier = _requireFrostOf(sender, ids[0]).tier;
        uint256 mergedAmount;
        uint256 mergedFrozenAt;

        for (uint256 i = 0; i < ids.length; ++i) {
            uint256 id = ids[i];
            Frost memory frost = _requireFrostOf(sender, id);

            _requireFree(id);
            require(frost.tier == tier, TierMismatch(id, frost.tier, tier));

            mergedAmount += frost.amount;
            if (frost.frozenAt > mergedFrozenAt) {
                mergedFrozenAt = frost.frozenAt;
            }

            _destroy(sender, id);
        }

        newId = _create(sender, tier, mergedAmount, mergedFrozenAt, block.timestamp);

        for (uint256 i = 0; i < ids.length; ++i) {
            emit Merged(ids[i], newId, sender, tier);
        }
    }

    function upgrade(uint256 id, uint8 newTier) external {
        require(newTier < TIERS, InvalidTier(newTier));

        address sender = _msgSender();
        Frost memory frost = _requireFrostOf(sender, id);
        require(newTier > frost.tier, NotAnUpgrade(id, frost.tier, newTier));

        _requireFree(id);

        _settle(sender);

        _tierTotal[sender][frost.tier] -= frost.amount;
        _tierTotal[sender][newTier] += frost.amount;
        totalFrozenIn[frost.tier] -= frost.amount;
        totalFrozenIn[newTier] += frost.amount;
        activeFrostsIn[frost.tier] -= 1;
        activeFrostsIn[newTier] += 1;

        _frosts[id].tier = newTier;
        _frosts[id].frozenAt = block.timestamp;
        _frosts[id].ownedAt = block.timestamp;

        _onStakeChanged(sender);

        emit Upgraded(id, sender, frost.tier, newTier, frost.amount, block.timestamp);
        emit FrostChanged(id);
    }

    function claim() external {
        address sender = _msgSender();

        uint256 availableAt = _accounts[sender].lastClaimAt + CLAIM_COOLDOWN;
        require(block.timestamp >= availableAt, ClaimTooEarly(sender, availableAt));
        require(_pending(sender) != 0, NothingToClaim(sender));

        _settle(sender);

        Account storage account = _accounts[sender];
        uint256 accrued = account.accruedNum / DENOM;
        uint256 available = availableRewards();
        uint256 claimAmount = accrued < available ? accrued : available;
        require(claimAmount != 0, RewardsDepleted());

        account.accruedNum -= claimAmount * DENOM;
        account.lastClaimAt = block.timestamp;

        _token.safeTransfer(sender, claimAmount);

        emit Claimed(sender, claimAmount);
    }

    function lock(uint256 id, uint256 lockTill) public override {
        super.lock(id, lockTill);

        emit FrostChanged(id);
    }

    function unlock(uint256 id) public override {
        bool wasLocked = isLocked(id);

        super.unlock(id);

        if (wasLocked) {
            emit FrostChanged(id);
        }
    }

    function transferPart(
        address from,
        uint256 id,
        uint256 amount,
        address to
    ) external returns (uint256 remainderId) {
        require(_msgSender() == _freezerMarket, OnlyMarketAccess());
        require(to != address(0) && to != address(this) && to != from, InvalidReceiver(to));
        require(amount != 0, ZeroAmount());

        Frost memory frost = _requireFrostOf(from, id);
        require(amount <= frost.amount, InsufficientFrost(id, frost.amount, amount));

        address lockedFor = lockedForOf(id);
        require(lockedFor == address(0) || lockedFor == from, FrostLocked(id, lockTillOf(id)));

        _requireAllowance(from, _msgSender());
        _requireSlot(to);

        remainderId = _move(id, frost, amount, to);

        emit Transferred(id, remainderId, from, to, frost.tier, amount, frost.frozenAt, lockTillOf(id));
    }

    function returnLocked(uint256 id) external {
        require(_msgSender() == _freezerMarket, OnlyMarketAccess());
        address to = lockedForOf(id);
        require(to != address(0), FrostNotLocked(id));

        _requireAllowance(to, _msgSender());

        Frost memory frost = _requireFrost(id);

        require(to != frost.owner, InvalidReceiver(to));

        _requireSlot(to);

        _move(id, frost, frost.amount, to);
        _unlock(id);

        emit Returned(id, frost.owner, to, frost.tier, frost.amount);
    }

    function token() public view override returns (IERC20) {
        return _token;
    }

    function freezerMarket() external view returns (address) {
        return _freezerMarket;
    }

    function freezeHook() external view returns (address) {
        return address(_freezeHook);
    }

    function getAccount(address owner) external view returns (AccountView memory) {
        Account memory account = _accounts[owner];

        return AccountView({
            accruedNum: account.accruedNum,
            lastAccrualAt: account.lastAccrualAt,
            lastClaimAt: account.lastClaimAt,
            firstFreezeAt: account.firstFreezeAt,
            frostCount: account.frostCount,
            frozenTotal: frozenOf(owner)
        });
    }

    function frozenOf(address owner) public view returns (uint256 total) {
        total = 0;
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            total += _tierTotal[owner][tier];
        }
    }

    function frozenByTierOf(address owner) external view returns (uint256[] memory out) {
        out = new uint256[](TIERS);
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            out[tier] = _tierTotal[owner][tier];
        }
    }

    function pendingOf(address owner) external view returns (uint256) {
        return _pending(owner);
    }

    function tierTotalOf(address owner, uint8 tier) external view returns (uint256) {
        return _tierTotal[owner][tier];
    }

    function tiers() external pure returns (TierInfo[] memory out) {
        out = new TierInfo[](TIERS);
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            out[tier] = TierInfo({tier: tier, term: _term(tier), weight: _weight(tier)});
        }
    }

    function totalFrozenByTier() external view returns (uint256[] memory out) {
        out = new uint256[](TIERS);
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            out[tier] = totalFrozenIn[tier];
        }
    }

    function activeFrostsByTier() external view returns (uint256[] memory out) {
        out = new uint256[](TIERS);
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            out[tier] = activeFrostsIn[tier];
        }
    }

    function unfreezeAtOf(uint256 id) external view returns (uint256) {
        Frost memory frost = _frosts[id];
        return frost.owner == address(0) ? 0 : _unfreezeAt(frost);
    }

    function getFrost(uint256 id) external view returns (FrostView memory) {
        return _frostView(id);
    }

    function getFrosts(uint256[] calldata ids) external view returns (FrostView[] memory out) {
        out = new FrostView[](ids.length);
        for (uint256 i = 0; i < ids.length; ++i) {
            out[i] = _frostView(ids[i]);
        }
    }

    function availableRewards() public view returns (uint256) {
        uint256 balance = _token.balanceOf(address(this));
        return balance > totalFrozen ? balance - totalFrozen : 0;
    }

    function isApprovedForAll(address owner, address operator) public view override returns (bool) {
        return _operatorPermitted(operator) && super.isApprovedForAll(owner, operator);
    }

    function _freeze(address owner, uint8 tier, uint256 amount) private returns (uint256 id) {
        _settle(owner);

        Account storage account = _accounts[owner];
        if (account.firstFreezeAt == 0) {
            account.firstFreezeAt = block.timestamp;
        }

        id = _create(owner, tier, amount, block.timestamp, block.timestamp);

        _tierTotal[owner][tier] += amount;
        totalFrozen += amount;
        totalFrozenIn[tier] += amount;
        _onStakeChanged(owner);

        emit Frozen(id, owner, tier, amount);
    }

    function _move(uint256 id, Frost memory frost, uint256 amount, address to) private returns (uint256 remainderId) {
        remainderId = 0;

        _settle(frost.owner);
        _settle(to);

        _tierTotal[frost.owner][frost.tier] -= amount;
        _tierTotal[to][frost.tier] += amount;
        _onStakeChanged(frost.owner);
        _onStakeChanged(to);

        _frosts[id].owner = to;
        _frosts[id].ownedAt = block.timestamp;
        _accounts[frost.owner].frostCount -= 1;
        _accounts[to].frostCount += 1;

        if (amount != frost.amount) {
            _frosts[id].amount = amount;
            remainderId = _create(frost.owner, frost.tier, frost.amount - amount, frost.frozenAt, frost.ownedAt);
        }

        emit FrostChanged(id);
    }

    function _create(
        address owner,
        uint8 tier,
        uint256 amount,
        uint256 frozenAt,
        uint256 ownedAt
    ) private returns (uint256 id) {
        id = nextFrostId++;
        _frosts[id] = Frost({amount: amount, owner: owner, tier: tier, frozenAt: frozenAt, ownedAt: ownedAt});
        _accounts[owner].frostCount += 1;
        activeFrosts += 1;
        activeFrostsIn[tier] += 1;

        emit FrostCreated(id, owner);
    }

    function _destroy(address owner, uint256 id) private {
        uint8 tier = _frosts[id].tier;

        delete _frosts[id];
        _accounts[owner].frostCount -= 1;
        activeFrosts -= 1;
        activeFrostsIn[tier] -= 1;

        _unlock(id);

        emit FrostRemoved(id, owner);
    }

    function _settle(address owner) private {
        Account storage account = _accounts[owner];
        uint256 earned = _accruedNumSince(owner, account.lastAccrualAt);
        if (earned != 0) {
            account.accruedNum += earned;
        }
        account.lastAccrualAt = block.timestamp;
    }

    function _notifyFreezeHook(address owner, address referrer, uint256 amount) private {
        IFreezeHook hook = _freezeHook;
        if (address(hook) != address(0)) {
            hook.onFreeze(owner, referrer, amount, _accounts[owner].firstFreezeAt);
        }
    }

    function _requireSlot(address owner) private view {
        require(_accounts[owner].frostCount < MAX_FROSTS, TooManyFrosts(owner, MAX_FROSTS));
    }

    function _requireFrost(uint256 id) private view returns (Frost memory frost) {
        frost = _frosts[id];
        require(frost.owner != address(0), NonexistentFrost(id));
    }

    function _requireFrostOf(address owner, uint256 id) private view returns (Frost memory frost) {
        frost = _requireFrost(id);
        require(frost.owner == owner, IncorrectOwner(id, frost.owner, owner));
    }

    function _requireFree(uint256 id) private view {
        require(!isLocked(id), FrostLocked(id, lockTillOf(id)));
    }

    function _accruedNumSince(address owner, uint256 since) private view returns (uint256) {
        if (since == 0 || since >= block.timestamp) {
            return 0;
        }

        uint256 elapsed = block.timestamp - since;
        uint256 weighted;
        for (uint8 tier = 0; tier < TIERS; ++tier) {
            uint256 total = _tierTotal[owner][tier];
            if (total != 0) {
                weighted += total * _weight(tier);
            }
        }
        return weighted * elapsed;
    }

    function _pending(address owner) private view returns (uint256) {
        Account storage account = _accounts[owner];
        return (account.accruedNum + _accruedNumSince(owner, account.lastAccrualAt)) / DENOM;
    }

    function _frostView(uint256 id) private view returns (FrostView memory out) {
        Frost memory frost = _frosts[id];
        if (frost.owner == address(0)) {
            return out;
        }

        out = FrostView({
            id: id,
            owner: frost.owner,
            tier: frost.tier,
            amount: frost.amount,
            frozenAt: frost.frozenAt,
            ownedAt: frost.ownedAt,
            unfreezeAt: _unfreezeAt(frost),
            lockedTill: lockTillOf(id),
            lockedFor: lockedForOf(id)
        });
    }

    function _ownerOf(uint256 id) internal view override returns (address) {
        return _frosts[id].owner;
    }

    function _operatorPermitted(address operator) internal view override returns (bool) {
        return operator == _freezerMarket;
    }

    function _requireAllowance(address owner, address operator) internal view override {
        _requireOperatorPermitted(operator);
        require(isApprovedForAll(owner, operator), NotApproved(owner, operator));
    }

    function _stakeOf(address account) internal view override returns (uint256) {
        return frozenOf(account);
    }

    function _collectCandidacyFee(address payer) internal override {
        _token.safeTransferFrom(payer, address(this), candidacyFee);
    }

    function _afterExecute(uint256) internal view override {
        uint256 balance = _token.balanceOf(address(this));
        require(balance >= totalFrozen, TreasuryBelowFrozen(balance, totalFrozen));
    }

    function _unfreezeAt(Frost memory frost) private pure returns (uint256) {
        return frost.frozenAt + _term(frost.tier);
    }

    function _term(uint8 tier) private pure returns (uint256) {
        return (uint256(tier) * 2 + 1) * YEAR;
    }

    function _weight(uint8 tier) private pure returns (uint256) {
        return uint256(tier) + 1;
    }
}

project/contracts/DexModule.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {DexBase} from "./DexBase.sol";
import {IUniswapV3Factory} from "./interfaces/dex/IUniswapV3Factory.sol";
import {INonfungiblePositionManager} from "./interfaces/dex/INonfungiblePositionManager.sol";
import {IV3SwapRouter} from "./interfaces/dex/IV3SwapRouter.sol";
import {IPoolManager} from "./interfaces/dex/IPoolManager.sol";

contract DexModule is DexBase {
    using SafeERC20 for IERC20;
    using SafeCast for uint256;
    using SafeCast for int256;

    enum V4Op {
        Modify,
        Swap
    }

    uint160 private constant MIN_SQRT_PRICE = 4295128739;
    uint160 private constant MAX_SQRT_PRICE = 1461446703485210103287273052203988822378723970342;

    uint256 private constant POOLS_SLOT = 6;

    modifier onlySelf() {
        require(msg.sender == address(this), NotSelf(msg.sender));
        _;
    }

    function init(address base, uint256 dexSellCap, Config calldata config) external {
        Store storage s = _store();
        require(s.base == address(0), AlreadyInitialized());
        require(
            base != address(0) &&
                config.usdt != address(0) &&
                config.usdc != address(0) &&
                config.wbtc != address(0) &&
                config.weth != address(0) &&
                config.uniV3Factory != address(0) &&
                config.uniV3PositionManager != address(0) &&
                config.uniV3Router != address(0) &&
                config.pancakeV3Factory != address(0) &&
                config.pancakeV3PositionManager != address(0) &&
                config.pancakeV3Router != address(0) &&
                config.uniV4PoolManager != address(0),
            ZeroDexAddress()
        );

        s.base = base;
        s.dexSellCap = dexSellCap;
        s.config = config;
    }

    function v3Mint(V3MintParams calldata p) external onlySelf returns (uint256 tokenId, uint256 liquidity) {
        (, INonfungiblePositionManager positionManager, ) = _v3(p.dex);
        _requireV3Pool(p.dex, p.token0, p.token1, p.fee);

        IERC20(p.token0).forceApprove(address(positionManager), p.amount0);
        IERC20(p.token1).forceApprove(address(positionManager), p.amount1);

        uint256 used0;
        uint256 used1;
        (tokenId, liquidity, used0, used1) = positionManager.mint(
            INonfungiblePositionManager.MintParams({
                token0: p.token0,
                token1: p.token1,
                fee: p.fee,
                tickLower: p.tickLower,
                tickUpper: p.tickUpper,
                amount0Desired: p.amount0,
                amount1Desired: p.amount1,
                amount0Min: p.amount0Min,
                amount1Min: p.amount1Min,
                recipient: address(this),
                deadline: block.timestamp
            })
        );

        IERC20(p.token0).forceApprove(address(positionManager), 0);
        IERC20(p.token1).forceApprove(address(positionManager), 0);

        _countSold(p.token0, used0);
        _countSold(p.token1, used1);

        emit V3Minted(p.dex, tokenId, p.token0, p.token1, p.fee, p.tickLower, p.tickUpper, liquidity, used0, used1);
    }

    function v3Increase(
        Dex dex,
        uint256 tokenId,
        uint256 amount0,
        uint256 amount1,
        uint256 amount0Min,
        uint256 amount1Min
    ) external onlySelf returns (uint256 liquidity, uint256 used0, uint256 used1) {
        (, INonfungiblePositionManager positionManager, ) = _v3(dex);
        require(positionManager.ownerOf(tokenId) == address(this), ForeignPosition(tokenId));

        (, , address token0, address token1, , , , , , , , ) = positionManager.positions(tokenId);
        _requirePair(token0, token1);

        IERC20(token0).forceApprove(address(positionManager), amount0);
        IERC20(token1).forceApprove(address(positionManager), amount1);

        (liquidity, used0, used1) = positionManager.increaseLiquidity(
            INonfungiblePositionManager.IncreaseLiquidityParams({
                tokenId: tokenId,
                amount0Desired: amount0,
                amount1Desired: amount1,
                amount0Min: amount0Min,
                amount1Min: amount1Min,
                deadline: block.timestamp
            })
        );

        IERC20(token0).forceApprove(address(positionManager), 0);
        IERC20(token1).forceApprove(address(positionManager), 0);

        _countSold(token0, used0);
        _countSold(token1, used1);

        emit V3Increased(dex, tokenId, liquidity, used0, used1);
    }

    function v3Decrease(
        Dex dex,
        uint256 tokenId,
        uint256 liquidity,
        uint256 amount0Min,
        uint256 amount1Min
    ) external onlySelf returns (uint256 amount0, uint256 amount1, uint256 fees0, uint256 fees1) {
        (, INonfungiblePositionManager positionManager, ) = _v3(dex);

        (, , address token0, address token1, , , , uint128 total, , , , ) = positionManager.positions(tokenId);
        _requirePair(token0, token1);
        require(liquidity <= total, InsufficientLiquidity(total, liquidity));

        if (liquidity != 0) {
            (amount0, amount1) = positionManager.decreaseLiquidity(
                INonfungiblePositionManager.DecreaseLiquidityParams({
                    tokenId: tokenId,
                    liquidity: liquidity.toUint128(),
                    amount0Min: amount0Min,
                    amount1Min: amount1Min,
                    deadline: block.timestamp
                })
            );
            _countBought(token0, amount0);
            _countBought(token1, amount1);
        }

        (fees0, fees1) = positionManager.collect(
            INonfungiblePositionManager.CollectParams({
                tokenId: tokenId,
                recipient: address(this),
                amount0Max: type(uint128).max,
                amount1Max: type(uint128).max
            })
        );

        fees0 = fees0 > amount0 ? fees0 - amount0 : 0;
        fees1 = fees1 > amount1 ? fees1 - amount1 : 0;

        bool burned = liquidity == total && total != 0;
        if (burned) {
            positionManager.burn(tokenId);
        }

        emit V3Decreased(dex, tokenId, liquidity, amount0, amount1, fees0, fees1, burned);
    }

    function v3Swap(
        Dex dex,
        address tokenIn,
        address tokenOut,
        uint24 fee,
        uint256 amountIn,
        uint256 amountOutMinimum
    ) external onlySelf returns (uint256 amountOut) {
        require(amountIn != 0, ZeroDexAmount());
        (, , IV3SwapRouter router) = _v3(dex);
        (address token0, address token1) = tokenIn < tokenOut ? (tokenIn, tokenOut) : (tokenOut, tokenIn);
        _requireV3Pool(dex, token0, token1, fee);

        uint256 before = IERC20(tokenIn).balanceOf(address(this));
        IERC20(tokenIn).forceApprove(address(router), amountIn);

        amountOut = router.exactInputSingle(
            IV3SwapRouter.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: amountOutMinimum,
                sqrtPriceLimitX96: 0
            })
        );

        IERC20(tokenIn).forceApprove(address(router), 0);
        uint256 spent = before - IERC20(tokenIn).balanceOf(address(this));

        _countSold(tokenIn, spent);
        _countBought(tokenOut, amountOut);

        emit Swapped(dex, tokenIn, tokenOut, spent, amountOut);
    }

    function v4Increase(
        IPoolManager.PoolKey calldata key,
        int24 tickLower,
        int24 tickUpper,
        uint256 liquidity,
        uint256 amount0Max,
        uint256 amount1Max
    ) external onlySelf returns (bytes32 positionId, uint256 amount0, uint256 amount1) {
        require(liquidity != 0, ZeroDexAmount());
        _requireV4Pool(key);

        uint256 fees0;
        uint256 fees1;
        (amount0, amount1, fees0, fees1) = _v4Modify(key, tickLower, tickUpper, liquidity.toInt256(), amount0Max, amount1Max);

        positionId = _positionId(key, tickLower, tickUpper);
        _open(positionId, key, tickLower, tickUpper);
        _store().v4Positions[positionId].liquidity += liquidity;

        _countSold(key.currency0, amount0);
        _countSold(key.currency1, amount1);

        emit V4Modified(positionId, liquidity.toInt256(), amount0, amount1, fees0, fees1);
    }

    function v4Decrease(
        bytes32 positionId,
        uint256 liquidity,
        uint256 amount0Min,
        uint256 amount1Min
    ) external onlySelf returns (uint256 amount0, uint256 amount1) {
        Store storage s = _store();
        V4Position memory position = s.v4Positions[positionId];
        require(position.liquidity != 0, UnknownPosition(positionId));
        require(liquidity <= position.liquidity, InsufficientLiquidity(position.liquidity, liquidity));

        uint256 fees0;
        uint256 fees1;
        (amount0, amount1, fees0, fees1) = _v4Modify(
            position.key,
            position.tickLower,
            position.tickUpper,
            -liquidity.toInt256(),
            amount0Min,
            amount1Min
        );

        _countBought(position.key.currency0, amount0);
        _countBought(position.key.currency1, amount1);

        if (liquidity == position.liquidity) {
            delete s.v4Positions[positionId];
            emit V4PositionClosed(positionId);
        } else {
            s.v4Positions[positionId].liquidity -= liquidity;
        }

        emit V4Modified(positionId, -liquidity.toInt256(), amount0, amount1, fees0, fees1);
    }

    function v4Swap(
        IPoolManager.PoolKey calldata key,
        bool zeroForOne,
        uint256 amountIn,
        uint256 amountOutMinimum
    ) external onlySelf returns (uint256 amountOut) {
        require(amountIn != 0, ZeroDexAmount());
        _requireV4Pool(key);

        bytes memory result = _poolManager().unlock(
            abi.encode(V4Op.Swap, abi.encode(key, zeroForOne, amountIn, amountOutMinimum))
        );

        uint256 spent;
        (spent, amountOut) = abi.decode(result, (uint256, uint256));

        (address tokenIn, address tokenOut) = zeroForOne
            ? (key.currency0, key.currency1)
            : (key.currency1, key.currency0);

        _countSold(tokenIn, spent);
        _countBought(tokenOut, amountOut);

        emit Swapped(Dex.UniswapV4, tokenIn, tokenOut, spent, amountOut);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        IPoolManager poolManager = _poolManager();
        require(msg.sender == address(poolManager), NotPoolManager(msg.sender));

        (V4Op op, bytes memory payload) = abi.decode(data, (V4Op, bytes));

        if (op == V4Op.Modify) {
            return _modifyInsideUnlock(poolManager, payload);
        }
        return _swapInsideUnlock(poolManager, payload);
    }

    function _modifyInsideUnlock(IPoolManager poolManager, bytes memory payload) private returns (bytes memory) {
        (
            IPoolManager.PoolKey memory key,
            int24 tickLower,
            int24 tickUpper,
            int256 liquidityDelta,
            uint256 bound0,
            uint256 bound1
        ) = abi.decode(payload, (IPoolManager.PoolKey, int24, int24, int256, uint256, uint256));

        (int256 delta, int256 fees) = poolManager.modifyLiquidity(
            key,
            IPoolManager.ModifyLiquidityParams({
                tickLower: tickLower,
                tickUpper: tickUpper,
                liquidityDelta: liquidityDelta,
                salt: bytes32(0)
            }),
            ""
        );

        (int256 delta0, int256 delta1) = _split(delta);
        _settle(poolManager, key.currency0, delta0);
        _settle(poolManager, key.currency1, delta1);

        return _bounded(delta, fees, liquidityDelta, bound0, bound1);
    }

    function _bounded(
        int256 delta,
        int256 fees,
        int256 liquidityDelta,
        uint256 bound0,
        uint256 bound1
    ) private pure returns (bytes memory) {
        (int256 delta0, int256 delta1) = _split(delta);
        (int256 fees0, int256 fees1) = _split(fees);
        int256 principal0 = delta0 - fees0;
        int256 principal1 = delta1 - fees1;

        uint256 amount0;
        uint256 amount1;
        if (liquidityDelta > 0) {
            amount0 = principal0 < 0 ? uint256(-principal0) : 0;
            amount1 = principal1 < 0 ? uint256(-principal1) : 0;
            require(amount0 <= bound0, AmountExceedsMax(amount0, bound0));
            require(amount1 <= bound1, AmountExceedsMax(amount1, bound1));
        } else {
            amount0 = principal0 > 0 ? uint256(principal0) : 0;
            amount1 = principal1 > 0 ? uint256(principal1) : 0;
            require(amount0 >= bound0, AmountBelowMin(amount0, bound0));
            require(amount1 >= bound1, AmountBelowMin(amount1, bound1));
        }
        return abi.encode(amount0, amount1, uint256(fees0), uint256(fees1));
    }

    function _swapInsideUnlock(IPoolManager poolManager, bytes memory payload) private returns (bytes memory) {
        (IPoolManager.PoolKey memory key, bool zeroForOne, uint256 amountIn, uint256 amountOutMinimum) = abi.decode(
            payload,
            (IPoolManager.PoolKey, bool, uint256, uint256)
        );

        int256 delta = poolManager.swap(
            key,
            IPoolManager.SwapParams({
                zeroForOne: zeroForOne,
                amountSpecified: -amountIn.toInt256(),
                sqrtPriceLimitX96: zeroForOne ? MIN_SQRT_PRICE + 1 : MAX_SQRT_PRICE - 1
            }),
            ""
        );

        (int256 delta0, int256 delta1) = _split(delta);
        _settle(poolManager, key.currency0, delta0);
        _settle(poolManager, key.currency1, delta1);

        (int256 inDelta, int256 outDelta) = zeroForOne ? (delta0, delta1) : (delta1, delta0);
        uint256 spent = inDelta < 0 ? uint256(-inDelta) : 0;
        uint256 amountOut = outDelta > 0 ? uint256(outDelta) : 0;
        require(amountOut >= amountOutMinimum, AmountBelowMin(amountOut, amountOutMinimum));
        return abi.encode(spent, amountOut);
    }

    function _v3(Dex dex) private view returns (IUniswapV3Factory, INonfungiblePositionManager, IV3SwapRouter) {
        Config storage c = _store().config;
        if (dex == Dex.UniswapV3) {
            return (
                IUniswapV3Factory(c.uniV3Factory),
                INonfungiblePositionManager(c.uniV3PositionManager),
                IV3SwapRouter(c.uniV3Router)
            );
        }
        if (dex == Dex.PancakeV3) {
            return (
                IUniswapV3Factory(c.pancakeV3Factory),
                INonfungiblePositionManager(c.pancakeV3PositionManager),
                IV3SwapRouter(c.pancakeV3Router)
            );
        }
        revert NotV3(dex);
    }

    function _countSold(address token, uint256 amount) private {
        Store storage s = _store();
        if (token != s.base || amount == 0) {
            return;
        }
        uint256 sold = s.dexSold + amount;
        require(sold <= s.dexSellCap, DexSellCapExceeded(sold, s.dexSellCap));
        s.dexSold = sold;
    }

    function _countBought(address token, uint256 amount) private {
        Store storage s = _store();
        if (token != s.base || amount == 0) {
            return;
        }
        uint256 sold = s.dexSold;
        s.dexSold = amount >= sold ? 0 : sold - amount;
    }

    function _poolManager() private view returns (IPoolManager) {
        return IPoolManager(_store().config.uniV4PoolManager);
    }

    function _requirePair(address token0, address token1) private view {
        require(isAllowedToken(token0), TokenNotAllowed(token0));
        require(isAllowedToken(token1), TokenNotAllowed(token1));
        require(token0 != token1, SamePair(token0));
        require(token0 < token1, UnsortedPair(token0, token1));
    }

    function _requireV3Pool(Dex dex, address token0, address token1, uint24 fee) private view {
        _requirePair(token0, token1);
        (IUniswapV3Factory factory, , ) = _v3(dex);
        require(factory.getPool(token0, token1, fee) != address(0), PoolNotFound());
    }

    function _requireV4Pool(IPoolManager.PoolKey calldata key) private view {
        require(key.hooks == address(0), HookedPool(key.hooks));
        _requirePair(key.currency0, key.currency1);

        bytes32 poolId = keccak256(abi.encode(key));
        bytes32 slot0 = _poolManager().extsload(keccak256(abi.encodePacked(poolId, POOLS_SLOT)));
        require(uint160(uint256(slot0)) != 0, PoolNotFound());
    }

    function _v4Modify(
        IPoolManager.PoolKey memory key,
        int24 tickLower,
        int24 tickUpper,
        int256 liquidityDelta,
        uint256 bound0,
        uint256 bound1
    ) private returns (uint256 amount0, uint256 amount1, uint256 fees0, uint256 fees1) {
        bytes memory result = _poolManager().unlock(
            abi.encode(V4Op.Modify, abi.encode(key, tickLower, tickUpper, liquidityDelta, bound0, bound1))
        );
        return abi.decode(result, (uint256, uint256, uint256, uint256));
    }

    function _settle(IPoolManager poolManager, address currency, int256 amount) private {
        if (amount < 0) {
            poolManager.sync(currency);
            IERC20(currency).safeTransfer(address(poolManager), uint256(-amount));
            poolManager.settle();
        } else if (amount > 0) {
            poolManager.take(currency, address(this), uint256(amount));
        }
    }

    function _open(bytes32 positionId, IPoolManager.PoolKey calldata key, int24 tickLower, int24 tickUpper) private {
        V4Position storage position = _store().v4Positions[positionId];
        if (position.liquidity != 0) {
            return;
        }
        position.key = key;
        position.tickLower = tickLower;
        position.tickUpper = tickUpper;
        emit V4PositionOpened(positionId, key.currency0, key.currency1, key.fee, key.tickSpacing, tickLower, tickUpper);
    }

    function _positionId(
        IPoolManager.PoolKey memory key,
        int24 tickLower,
        int24 tickUpper
    ) private pure returns (bytes32) {
        return keccak256(abi.encode(key, tickLower, tickUpper));
    }

    function _split(int256 delta) private pure returns (int256 amount0, int256 amount1) {
        amount0 = int256(int128(delta >> 128));
        amount1 = int256(int128(delta));
    }
}

